
import React, { useState, useEffect } from "react";

import "./styles.css"

import {  SvgIcon_Cmpt, DeleteAlert_Cmpt } from "../../../components";
import { NavLink, useNavigate, useLocation } from "react-router-dom";
import { updStore, getStore, gen16CodeId,  parseQuery, qryKClient,  qryStore, fetchEncryptStream, aisleJSON } from "../../../stores/Utils";

import {  getById_notary, getall_categories, getFNMLabels } from "../services/customer_fetch_service";


import { 
	InformationView_Cmpt, MovementUpdate_Cmpt
} from "..";
import { OpenModal } from "../../../components/DialogHRM";





	
const Svg = SvgIcon_Cmpt();



const InformationView = InformationView_Cmpt();



const DeleteAlert = DeleteAlert_Cmpt();

const MovementUpdate = MovementUpdate_Cmpt();



const CustomerDetail  = ({ }) => {
	const [, set_obs] = useState(1);
	//const [view, setView] = useState(1)




	let location = useLocation();

	const navigate = useNavigate();
	const searchHash = location.search?.split("?")?.[1];
	const router = parseQuery(searchHash);

	let cId = router?.cId;
	let view = router?.view *1;

	let itm = router?.view *1;
	
	useEffect(() => {
		updStore( "preview_mov_dmz",null);
		updStore("image_preview_mov",null);
		updStore("image_url_mov",null);
		updStore("image_mov_text",null);
		
		getById_notary(cId,getCateg);

		
	},[cId]);


	const updObs =  () => {
		set_obs(gen16CodeId())
	}

	const getCateg =  () => {

		let itm = getStore(qryKClient())
		let categoryLabel = getStore("categories_ids")?.[itm?.categoryId]?.name;
		if(!categoryLabel){
			getall_categories(updObs);
		}
		else{
			updObs();
		}
	}


	let clientItm = getStore(qryKClient());


	

	const _updItm = () =>{
		navigate({
			"pathname": "/movements" ,
			"search": "?tab=movements"
		});

	}
	const openUpdView =  () => {

		updStore(qryKClient()+"_upd", clientItm);
		updStore(qryKClient()+"_upd_bck", aisleJSON(clientItm));
		

		let modal_data = {};
		modal_data["zIndex"] = 450;
		modal_data["height"] = "80vh";
		// data['observeResize']=true;
		modal_data["props"] = { minHeight: "1vh", overlay: true };
		modal_data["content"] =	<MovementUpdate confirm={_updItm} />
		OpenModal(modal_data);
	}

	const confirmDelete =  (v)  => {
		let bdyq2 = {...getStore(qryStore())?.delete__incms_expns};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			movementId: clientItm?.movementId
		}
		fetchData(bdyq2)
	};


	const fetchData  = async (bdyq2)  => {
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td && !td.error) {
			navigate({
				"pathname": "/movements" ,
				"search": "?tab=movements"
			});
		}
	}


	const OpenDeleteAlert =  () => {
		let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
		if(Date.now() > lastTimeCallModal){
			updStore("lastTimeCallModal", Date.now()+320);
			
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <DeleteAlert
				confirm={confirmDelete}
				lbl_p={"Delete"} 
				lbl_span={"Una vez eliminado no podra ser recuperado"}
				colors={{
					"--alert-title-color":"var(--primary-blue--backg-30)",
					"--alert-desc-color":"var(--light-300)",
					
				}}
			/>
			OpenModal(modaldata);
		}
	}
		

	
	const goto =  (v)  => {
		window.scrollTo(0,0);
	}


	console.log(clientItm)


	let lblType = clientItm?.movementType === "expense"? 40: 42;

	
	return (
		<div className="customer_bx ">

			<div className="ebEwoI">
				<div className="jKZvHt " onClick={goto}>
					<NavLink className={`bXnHIV `}  to={{
							"pathname": "/movements" ,
							"search": "?tab=movements"
					}}>
						<Svg
							name={"arrowBack"} 
							size={24}
							color={"var(--light-200)"}
						/>
						<div className="eULkqP"></div>
					</NavLink>
				</div>
				<div className="flexSpace"/>
				<div className="_dsplFlx" >
						
					<div className={`lh-default ${lblType === 40?"red_orangered":"blue_30"}`} style={{marginRight:12}}>
						<div className="IssueLabel hrm_labelColor hrm_labelColor_ft16" >
							{getFNMLabels(lblType)}
						</div>
					</div>
					<div className="flexSpace"/>
				
				</div>
				<div className="flexSpace"/>
				<div className="icon_action"	onClick={openUpdView}>
					<Svg name={"outline_edit"} color={"var(--light-200)"}	/>
				</div>
				<div className="icon_action"	onClick={OpenDeleteAlert}>
					<Svg name={"outline_delete"}  color={"var(--light-200)"}/>
				</div>
			</div>
				
			<div style={{paddingTop: 4}}/>

			
			<OpacityView viewId={1} activeView={view}>
					
					<InformationView
						updObPrnt={updObs}
					/>
			</OpacityView>


		</div>
	)

}

export default CustomerDetail;








const FloatingSideMenu  = ({ tabs, active, updTab }) => {
	const [obs, set_obs] = useState(1);
	
	const confirm =  () => {

	}
	const clickFloatTab =  () => {
		window.scrollTo(0,0);
	}
	
	return (
		<div className="dashboard_menu">
			<div className="dashboard_fixed" style={{margin: 5, borderRight: "1px solid var(--ytcp-text-secondary);)"}}>
					
				<div className={"option_list"}>
					{tabs?.map(tb=>{
						return (
							<NavLink 
								key={tb.index} 
								className={`bXnHlS ${active === tb.index? "activeTab":""}`}  
								to={tb.navTo}
								onClick={clickFloatTab}
							>
								<Svg
									name={tb.icon} 
									size={22}
								/>
								<div className="eULkqP">{tb.label}</div>
							</NavLink>
						)
					})}
				</div>
			</div>
		</div>
	)
}












const OpacityView  = ({ viewId, activeView, children }) => {
	return(
		<div className={"opacityView"} style={{opacity : viewId=== activeView?1:0, marginTop: 29 }}>
			{viewId=== activeView?children:null}
		</div>
	)

}




	
const convert2A =  (v)=>{
	let nob = {}
	if(Array.isArray(v)){
		v.map(it=>{
			nob[gen16CodeId()] = it;
		})
	}
	else{
		return v;
	}
	return nob;
}
